 function sample(now){const runtime=window.driftCarRuntime,pose=runtime?.getRenderState?.(),state=runtime?.getState?.();if(!pose||!state?.active||pose.grounded===false){previous=undefined;return;}const burnout=state.keys?.includes('KeyW')&&state.keys?.includes('Space')&&!state.keys?.includes('KeyS'),speed=Math.hypot(...pose.velocity),slipping=burnout||speed>4&&(Math.abs(state.tireSlip??state.sideSlip)>.14||(pose.braking&&Math.abs(pose.steer)>.08));const grass=state.surfaceMaterial==="grass";if(!(grass?speed>.7:slipping)){previous=undefined;return;}const wheels=[wheel(pose,-.8),wheel(pose,.8)];if(previous?.material!==state.surfaceMaterial)previous=undefined;if(!previous){previous=wheels;previous.material=state.surfaceMaterial;return;}const distance=Math.hypot(wheels[0][0]-previous[0][0],wheels[0][1]-previous[0][1])/wheels[0][3];if(distance>8){previous=wheels;return;}if(distance<(burnout?.04:.3)){if(burnout&&(!previous.stampTime||now-previous.stampTime>250)){for(const w of wheels){const d=.15*w[3],sx=Math.sin(pose.heading)*d,sy=Math.cos(pose.heading)*d;segments.push({a:[w[0]-sx,w[1]-sy,w[2],w[3]],b:[w[0]+sx,w[1]+sy,w[2],w[3]],time:now,grass});}previous.stampTime=now;if(segments.length>maxSegments)segments.splice(0,segments.length-maxSegments);}return;}for(let i=0;i<2;i++)segments.push({a:previous[i],b:wheels[i],time:now,grass});previous=wheels;previous.material=state.surfaceMaterial;if(segments.length>maxSegments)segments.splice(0,segments.length-maxSegments);}
